<script setup lang="ts">
import { ref, onMounted, watch } from 'vue';
import { Plus, Clock3, Ban } from 'lucide-vue-next';
import { api, send, canEdit, today, time, labels, type Employee } from '../api';
import Modal from '../components/Modal.vue';
const date = ref(today()), rows = ref<any[]>([]), employees = ref<Employee[]>([]), error = ref(''), message = ref(''), busy = ref(false), showForm = ref(false), voidRow = ref<any>(null), voidReason = ref('');
const form = ref({ employeeId: '', kind: 'AM_IN', occurredAt: `${today()}T08:00`, reason: '' }); let key = crypto.randomUUID();
async function load() { try { rows.value = await api(`/attendance?date=${date.value}`); } catch (e) { error.value = (e as Error).message; } }
onMounted(async () => { await load(); try { employees.value = await api('/employees'); } catch (e) { error.value = (e as Error).message; } }); watch(date, load);
function open() { error.value = ''; key = crypto.randomUUID(); form.value = { employeeId: employees.value.find(e => e.active)?.id ?? '', kind: 'AM_IN', occurredAt: `${date.value}T08:00`, reason: '' }; showForm.value = true; }
async function save() { busy.value = true; error.value = ''; try { await api('/attendance/manual', send('POST', { ...form.value, occurredAt: new Date(`${form.value.occurredAt}:00+08:00`).toISOString(), key })); showForm.value = false; message.value = 'Attendance recorded. This manual entry is included in the audit trail.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function voidPunch() { busy.value = true; error.value = ''; try { await api(`/attendance/${voidRow.value.id}/void`, send('POST', { reason: voidReason.value })); voidRow.value = null; message.value = 'Record voided. The original entry is retained for review.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><p v-if="message" class="alert success" role="status">{{ message }}</p><p v-if="error && !showForm && !voidRow" class="alert error" role="alert">{{ error }}</p><section class="panel"><div class="panel-heading"><div><h2>Daily attendance</h2><p>Review punches and record approved corrections</p></div><button v-if="canEdit()" class="button primary" @click="open"><Plus :size="17" /> Manual entry</button></div><div class="filter-bar"><label class="inline-label">Service date<input v-model="date" type="date" required /></label><span class="muted small-text">{{ rows.filter(r => !r.voidedAt).length }} active punches</span></div><div v-if="!rows.length" class="empty-state"><Clock3 :size="32" /><h3>No attendance for this date</h3><p>Choose another day or add an approved manual entry.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Employee</th><th>Event</th><th>Philippine time</th><th>Source</th><th>Note</th><th v-if="canEdit()">Action</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" :class="{ 'void-row': r.voidedAt }"><td><strong class="cell-title">{{ r.employee.firstName }} {{ r.employee.lastName }}</strong><small class="cell-subtitle">{{ r.employee.employeeNo }}</small></td><td><span class="badge neutral">{{ labels[r.kind] }}</span></td><td class="numeric">{{ time(r.occurredAt) }}</td><td>{{ r.source === 'FACE' ? 'Face scan' : 'Manual' }}</td><td class="note-cell">{{ r.voidedAt ? `Voided: ${r.voidReason}` : r.reason ?? 'Verified at kiosk' }}</td><td v-if="canEdit()"><button v-if="!r.voidedAt" class="text-button destructive" @click="voidRow = r; voidReason = ''; error = ''"><Ban :size="15" /> Void</button><span v-else class="badge neutral">Voided</span></td></tr></tbody></table></div></section><p class="page-note">Corrections preserve the original punch. Void an incorrect record before entering its replacement.</p>
<Modal v-if="showForm" title="Record manual attendance" @close="!busy && (showForm = false)"><form @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{ error }}</p><p class="muted">Use this for approved corrections or employees using an alternative to face verification. All times below are in the Philippines.</p><label>Employee<select v-model="form.employeeId" required><option v-for="e in employees.filter(e => e.active)" :key="e.id" :value="e.id">{{ e.lastName }}, {{ e.firstName }} · {{ e.employeeNo }}</option></select></label><div class="form-grid"><label>Attendance event<select v-model="form.kind"><option v-for="(label, k) in labels" :key="k" :value="k">{{ label }}</option></select></label><label>Date & time (PHT)<input v-model="form.occurredAt" type="datetime-local" required /></label></div><label>Reason for manual entry<textarea v-model="form.reason" required minlength="5" maxlength="500" rows="3" placeholder="Explain the approved correction or alternative entry." /></label><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="showForm = false">Cancel</button><button class="button primary" :disabled="busy || !form.employeeId">{{ busy ? 'Saving…' : 'Record attendance' }}</button></div></form></Modal>
<Modal v-if="voidRow" title="Void attendance record" @close="!busy && (voidRow = null)"><form @submit.prevent="voidPunch"><p v-if="error" class="alert error" role="alert">{{ error }}</p><p>Void {{ labels[voidRow.kind] }} at {{ time(voidRow.occurredAt) }} for <strong>{{ voidRow.employee.firstName }} {{ voidRow.employee.lastName }}</strong>?</p><label>Reason<textarea v-model="voidReason" required minlength="5" maxlength="500" rows="3" /></label><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="voidRow = null">Cancel</button><button class="button danger" :disabled="busy">{{ busy ? 'Saving…' : 'Void record' }}</button></div></form></Modal></template>
